573	    private String getProtocolValue(Element el, Attribute attr) {
574	        String value = el.absUrl(attr.getKey());
575	        if (value.isEmpty() && !StringUtil.hasHttpScheme(attr.getValue()))
576	            value = attr.getValue(); // if it could not be made abs, run as-is to allow custom unknown protocols
577	        return value;
578	    }
