720	    /**
721	     Cleans a {@code srcset} attribute value, candidate by candidate. Candidates with invalid syntax (missing URL,
722	     empty candidates, malformed descriptors, or trailing junk) are dropped, as are those whose URL fails the
723	     protocol checks configured for the attribute on this tag. Surviving candidates keep their original order and
724	     are normalized to {@code url descriptor, url descriptor} form. Does not throw on malformed input.
725	
726	     @param tagName the tag the attribute is on; selects the applicable protocol configuration
727	     @param el the element the attribute is on, to resolve URLs against its base URI
728	     @param value the source srcset attribute value
729	     @return the cleaned value, or {@code null} if no candidates survive (in which case the attribute is removed)
730	     */
731	    String cleanSrcset(String tagName, Element el, String value) {
732	        Set<Protocol> protocols = srcsetProtocols(TagName.valueOf(tagName));
733	        StringBuilder sb = StringUtil.borrowBuilder();
734	
735	        int pos = 0, length = value.length();
736	        while (pos <= length) {
737	            // find the end of this candidate: a comma separates candidates, unless it is within the URL and directly
738	            // followed by a non-whitespace, non-comma character (e.g. the comma in a data: URL). Consecutive
739	            // separators produce empty candidates, which are invalid.
740	            int start = pos, end = pos;
741	            boolean inUrl = true; // still scanning the URL run (no whitespace after URL content yet)
742	            boolean started = false; // seen non-whitespace content in this candidate
743	            while (end < length) {
744	                char c = value.charAt(end);
745	                if (c == ',') {
746	                    if (inUrl && started && end + 1 < length && !isSrcsetSpace(value.charAt(end + 1)) && value.charAt(end + 1) != ',')
747	                        end++; // comma is part of the URL
748	                    else
749	                        break; // candidate separator
750	                } else {
751	                    if (isSrcsetSpace(c)) {
752	                        if (started) inUrl = false;
753	                    } else {
754	                        started = true;
755	                    }
756	                    end++;
757	                }
758	            }
759	            appendSrcsetCandidate(el, value, start, end, protocols, sb);
760	            if (end >= length) break;
761	            pos = end + 1; // step past the separator comma
762	        }
763	
764	        if (sb.length() == 0) {
765	            StringUtil.releaseBuilderVoid(sb);
766	            return null;
767	        }
768	        return StringUtil.releaseBuilder(sb);
769	    }
770	
771	    /**
772	     Validates and appends a single srcset candidate (the {@code value} range {@code start}..{@code end}) to
773	     {@code sb}. Invalid or unsafe candidates are silently dropped; their text is never recombined into new URLs.
774	     */
775	    private void appendSrcsetCandidate(Element el, String value, int start, int end, Set<Protocol> protocols, StringBuilder sb) {
776	        // trim ASCII whitespace from the candidate
777	        while (start < end && isSrcsetSpace(value.charAt(start))) start++;
778	        while (end > start && isSrcsetSpace(value.charAt(end - 1))) end--;
779	        if (start == end) return; // empty candidate (e.g. from consecutive separators)
780	
781	        // the URL is the leading run of non-whitespace
782	        int urlEnd = start;
783	        while (urlEnd < end && !isSrcsetSpace(value.charAt(urlEnd))) urlEnd++;
784	        String url = value.substring(start, urlEnd);
785	        if (isOrphanDescriptor(url)) return; // a descriptor cannot stand in for the required URL
786	
787	        // an optional descriptor may follow, introduced by at least one ASCII space
788	        String descriptor = null;
789	        if (urlEnd < end) {
790	            if (value.charAt(urlEnd) != ' ') return; // the descriptor must be space-separated from the URL
791	            int descStart = urlEnd;
792	            while (descStart < end && value.charAt(descStart) == ' ') descStart++;
793	            int descEnd = descStart;
794	            while (descEnd < end && !isSrcsetSpace(value.charAt(descEnd))) descEnd++;
795	            if (descEnd != end) return; // unexpected content after the descriptor (e.g. a second descriptor)
796	            descriptor = value.substring(descStart, descEnd);
797	            if (!isValidSrcsetDescriptor(descriptor)) return;
798	        }
799	
800	        if (protocols != null && !isSafeSrcsetUrl(el, url, protocols)) return;
801	
802	        if (sb.length() > 0) sb.append(", ");
803	        sb.append(url);
804	        if (descriptor != null) sb.append(' ').append(descriptor);
805	    }
806	
807	    /**
808	     Finds the protocol configuration applicable to {@code srcset} on the given tag, following the same tag to
809	     {@code :all} fallback as {@link #isSafeAttribute}, so that per-tag differences neither widen nor narrow each
810	     other. Returns {@code null} when URLs are unrestricted.
811	     */
812	    private Set<Protocol> srcsetProtocols(TagName tag) {
813	        Set<AttributeKey> okSet = attributes.get(tag);
814	        if (okSet != null && okSet.contains(SrcsetKey)) {
815	            Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
816	            return attrProts != null ? attrProts.get(SrcsetKey) : null;
817	        }
818	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
819	        if (enforcedSet != null && enforcedSet.containsKey(SrcsetKey)) return null;
820	        return !tag.equals(AllTag) ? srcsetProtocols(AllTag) : null;
821	    }
822	
823	    private boolean isSafeSrcsetUrl(Element el, String url, Set<Protocol> protocols) {
824	        // apply the same structural rules as for a single-value URL attribute: no control characters or inner
825	        // whitespace, and no bare scheme (e.g. "javascript:") with nothing after the colon
826	        if (!isSoundUrlValue(url)) return false;
827	        // the scheme must still be allowed after percent-decoding and stripping control characters, so that a
828	        // dangerous scheme cannot hide behind e.g. "java%73cript:", "%6Aavascript:", "%00javascript:", or leading
829	        // whitespace and control bytes
830	        if (!isSafeDecodedScheme(url, protocols)) return false;
831	
832	        String value = StringUtil.resolve(el.baseUri(), url);
833	        if (value.isEmpty() && !StringUtil.hasHttpScheme(url))
834	            value = url; // if it could not be made absolute, run as-is to allow custom unknown protocols
835	        return isSafeProtocol(value, protocols);
836	    }
837	
838	    /**
839	     Checks the scheme of a candidate URL against the configured protocols, after undoing obfuscations that could hide
840	     a dangerous scheme from a naive prefix check. A real URL scheme is terminated by a <b>literal</b> colon, so the
841	     raw value is scanned for its first colon; percent-encoded bytes and ASCII control characters in the scheme run
842	     before that colon are normalized (e.g. {@code java%73cript:}, {@code %6Aavascript:}, and {@code java%00script:}
843	     all reveal {@code javascript:}). A value with no literal-colon scheme (a relative reference such as
844	     {@code x%3Ay.jpg} or an already-encoded {@code http%3a//host}) is left to the standard base-URI resolution
845	     rules, exactly like a single-value URL attribute. Never throws.
846	     */
847	    private static boolean isSafeDecodedScheme(String url, Set<Protocol> protocols) {
848	        int colon = url.indexOf(':');
849	        if (colon <= 0) return true; // no literal scheme separator: a relative / protocol-relative reference
850	
851	        String head = url.substring(0, colon);
852	        // the scheme run may only contain scheme characters or percent-escapes; anything else (e.g. a leading "//")
853	        // means this colon is not a scheme separator
854	        int length = head.length();
855	        boolean sawEscape = false;
856	        for (int i = 0; i < length; i++) {
857	            char c = head.charAt(i);
858	            if (c == '%') { sawEscape = true; continue; }
859	            boolean schemeChar = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
860	                || (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.';
861	            if (!schemeChar) return true; // not a scheme; defer to base-URI resolution
862	        }
863	        if (!sawEscape) return true; // an unescaped scheme is checked by the normal resolved-URL protocol test
864	
865	        // decode the escaped bytes and drop any revealed control characters, then confirm a well-formed scheme
866	        String decoded = stripControlChars(percentDecode(head));
867	        if (decoded.isEmpty() || !isSchemeAlpha(decoded.charAt(0))) return true;
868	        for (int i = 0; i < decoded.length(); i++) {
869	            char c = decoded.charAt(i);
870	            boolean schemeChar = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
871	                || (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.';
872	            if (!schemeChar) return true; // decoding revealed a non-scheme byte, so it is a relative reference
873	        }
874	
875	        String scheme = lowerCase(decoded);
876	        for (Protocol protocol : protocols) {
877	            String prot = protocol.toString();
878	            if (!prot.equals("#") && scheme.equals(prot)) return true; // the "#" pseudo-protocol never matches a scheme
879	        }
880	        return false;
881	    }
882	
883	    /** Removes ASCII control characters (0x00-0x1F and DEL), which browsers ignore when reading a URL scheme. */
884	    private static String stripControlChars(String value) {
885	        int length = value.length();
886	        StringBuilder stripped = null;
887	        for (int i = 0; i < length; i++) {
888	            char c = value.charAt(i);
889	            if (c <= 0x1f || c == 0x7f) {
890	                if (stripped == null) {
891	                    stripped = new StringBuilder(length);
892	                    stripped.append(value, 0, i);
893	                }
894	            } else if (stripped != null) {
895	                stripped.append(c);
896	            }
897	        }
898	        return stripped != null ? stripped.toString() : value;
899	    }
900	
901	    /**
902	     Leniently decodes {@code %XX} percent-escapes to their (ISO-8859-1 mapped) character. Malformed or incomplete
903	     escapes are left as-is. Used only to reveal an obfuscated URL scheme, so decoding never throws and charset
904	     subtleties outside the ASCII scheme are irrelevant.
905	     */
906	    private static String percentDecode(String url) {
907	        int length = url.length();
908	        if (length < 3 || url.indexOf('%') == -1) return url;
909	        StringBuilder decoded = null;
910	        for (int i = 0; i < length; i++) {
911	            char c = url.charAt(i);
912	            if (c == '%' && i + 2 < length) {
913	                int hi = Character.digit(url.charAt(i + 1), 16);
914	                int lo = Character.digit(url.charAt(i + 2), 16);
915	                if (hi >= 0 && lo >= 0) {
916	                    if (decoded == null) {
917	                        decoded = new StringBuilder(length);
918	                        decoded.append(url, 0, i);
919	                    }
920	                    decoded.append((char) ((hi << 4) | lo));
921	                    i += 2;
922	                    continue;
923	                }
924	            }
925	            if (decoded != null) decoded.append(c);
926	        }
927	        return decoded != null ? decoded.toString() : url;
928	    }
929	
930	    /**
931	     * Tests if a candidate's first (and only) whitespace-delimited token is a descriptor with no URL in front of it,
932	     * rather than a relative URL. Such an orphan has the <i>shape</i> of a width or density descriptor: a lowercase
933	     * {@code w} or {@code x} suffix, an optional single leading sign, and a non-empty remaining run of only digits and
934	     * dots, e.g. {@code 2x}, {@code 100w}, {@code 1.5x}, {@code 0w}, {@code -1x}, {@code +1x}, {@code 1.x},
935	     * {@code .5x}, or {@code 1.5.2x}. This is a purely syntactic shape test (it does not require the number to be
936	     * valid), because a token that can only be read as a descriptor attempt supplies no decidable URL. A genuine
937	     * relative reference always carries something a descriptor number can never hold — another letter
938	     * ({@code 1e3x}, {@code 1X}, {@code 2x.jpg}), a path separator ({@code ../2x}), or an internal or second sign
939	     * ({@code 1-2x}, {@code ++2x}) — and so is never mistaken for an orphan.
940	     */
941	    private static boolean isOrphanDescriptor(String token) {
942	        int length = token.length();
943	        if (length < 2) return false; // a bare "w"/"x" is a possible relative reference, not a descriptor attempt
944	        char suffix = token.charAt(length - 1);
945	        if (suffix != 'w' && suffix != 'x') return false;
946	        int i = 0;
947	        if (token.charAt(0) == '+' || token.charAt(0) == '-') i++; // at most one, leading sign
948	        if (i == length - 1) return false; // just a sign and suffix (e.g. "+w"): a relative reference, not a number
949	        for (; i < length - 1; i++) {
950	            char c = token.charAt(i);
951	            boolean numberChar = (c >= '0' && c <= '9') || c == '.';
952	            if (!numberChar) return false; // a letter, separator, or internal sign marks a real URL
953	        }
954	        return true;
955	    }
956	
957	    /**
958	     Validates a srcset descriptor: a positive integer followed by a lowercase {@code w} (e.g. {@code 100w}), or a
959	     positive number (digits, or digits.digits) followed by a lowercase {@code x} (e.g. {@code 2x}, {@code 1.5x}).
960	     Signs, exponents, a dot missing a side, and zero values are all invalid.
961	     */
962	    private static boolean isValidSrcsetDescriptor(String descriptor) {
963	        int length = descriptor.length();
964	        if (length < 2) return false;
965	        String number = descriptor.substring(0, length - 1);
966	        switch (descriptor.charAt(length - 1)) {
967	            case 'w': return isPositiveInteger(number);
968	            case 'x': return isPositiveNumber(number);
969	            default:  return false;
970	        }
971	    }
972	
973	    /** Tests if the value is all digits and greater than zero. */
974	    private static boolean isPositiveInteger(String number) {
975	        boolean nonZero = false;
976	        for (int i = 0, length = number.length(); i < length; i++) {
977	            char c = number.charAt(i);
978	            if (c < '0' || c > '9') return false;
979	            if (c != '0') nonZero = true;
980	        }
981	        return nonZero;
982	    }
983	
984	    /** Tests if the value is digits, or digits.digits, and greater than zero. */
985	    private static boolean isPositiveNumber(String number) {
986	        int dot = number.indexOf('.');
987	        if (dot == -1) return isPositiveInteger(number);
988	        if (number.indexOf('.', dot + 1) != -1) return false; // at most one dot
989	        String integer = number.substring(0, dot);
990	        String fraction = number.substring(dot + 1);
991	        if (!isDigits(integer) || !isDigits(fraction)) return false; // the dot needs digits on both sides
992	        return isPositiveInteger(integer) || isPositiveInteger(fraction);
993	    }
994	
995	    private static boolean isDigits(String value) {
996	        for (int i = 0, length = value.length(); i < length; i++) {
997	            char c = value.charAt(i);
998	            if (c < '0' || c > '9') return false;
999	        }
1000	        return value.length() > 0;
1001	    }
1002	
1003	    /** The ASCII whitespace characters: space, tab, newline, carriage return, and form feed. */
1004	    private static boolean isSrcsetSpace(char c) {
1005	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
1006	    }
1007	
1008	    /** Tests if the character is an ASCII letter, the required first character of a URL scheme. */
1009	    private static boolean isSchemeAlpha(char c) {
1010	        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
1011	    }
1012	
1013	    /**
1014	     Check if a URL attribute should be normalized to an absolute URL in the cleaned output. Uses the configured
1015	     protocols for that tag+attribute pair, falling back to {@code :all} only if the tag does not define the
1016	     attribute.
1017	     */
1018	    boolean shouldAbsUrl(String tagName, String attrKey) {
1019	        if (preserveRelativeLinks) return false;
1020	        return shouldAbsUrl(TagName.valueOf(tagName), AttributeKey.valueOf(attrKey));
1021	    }
1022	
1023	    private boolean shouldAbsUrl(TagName tag, AttributeKey key) {
1024	        Set<AttributeKey> allowedAttrs = attributes.get(tag);
1025	        if (allowedAttrs != null && allowedAttrs.contains(key)) {
1026	            Map<AttributeKey, Set<Protocol>> protocolsByAttr = protocols.get(tag);
1027	            return protocolsByAttr != null && protocolsByAttr.containsKey(key);
1028	        }
1029	
1030	        Map<AttributeKey, AttributeValue> enforcedAttrs = enforcedAttributes.get(tag);
1031	        if (enforcedAttrs != null && enforcedAttrs.containsKey(key)) return false;
1032	
1033	        return !tag.equals(AllTag) && shouldAbsUrl(AllTag, key);
1034	    }
1035	
1036	    private static boolean isValidAnchor(String value) {
1037	        return value.startsWith("#") && !value.matches(".*\\s.*");
1038	    }
1039	
1040	    /**
1041	     Gets the Attributes that should be enforced for a given tag
1042	     * @param tagName the tag
1043	     * @return the attributes that will be enforced; empty if none are set for the given tag
1044	     */
1045	    public Attributes getEnforcedAttributes(String tagName) {
1046	        Attributes attrs = new Attributes();
1047	        TagName tag = TagName.valueOf(tagName);
1048	        if (enforcedAttributes.containsKey(tag)) {
1049	            Map<AttributeKey, AttributeValue> keyVals = enforcedAttributes.get(tag);
1050	            for (Map.Entry<AttributeKey, AttributeValue> entry : keyVals.entrySet()) {
1051	                attrs.put(entry.getKey().toString(), entry.getValue().toString());
1052	            }
1053	        }
1054	        return attrs;
1055	    }
1056	    
1057	    // named types for config. All just hold strings, but here for my sanity.
1058	
1059	    static class TagName extends TypedValue {
1060	        TagName(String value) {
1061	            super(value);
1062	        }
1063	
1064	        static TagName valueOf(String value) {
1065	            return new TagName(Normalizer.lowerCase(value));
1066	        }
1067	    }
1068	
1069	    static class AttributeKey extends TypedValue {
1070	        AttributeKey(String value) {
1071	            super(value);
1072	        }
1073	
1074	        static AttributeKey valueOf(String value) {
1075	            return new AttributeKey(Normalizer.lowerCase(value));
1076	        }
1077	    }
1078	
1079	    static class AttributeValue extends TypedValue {
1080	        AttributeValue(String value) {
1081	            super(value);
1082	        }
1083	
1084	        static AttributeValue valueOf(String value) {
1085	            return new AttributeValue(value);
1086	        }
1087	    }
1088	
1089	    static class Protocol extends TypedValue {
1090	        Protocol(String value) {
1091	            super(value);
1092	        }
1093	
1094	        static Protocol valueOf(String value) {
1095	            return new Protocol(value);
1096	        }
1097	    }
1098	
1099	    abstract static class TypedValue {
1100	        private final String value;
1101	
1102	        TypedValue(String value) {
1103	            Validate.notNull(value);
1104	            this.value = value;
1105	        }
1106	
1107	        @Override
1108	        public int hashCode() {
1109	            return value.hashCode();
1110	        }
1111	
1112	        @Override
1113	        public boolean equals(Object obj) {
1114	            if (this == obj) return true;
1115	            if (obj == null || getClass() != obj.getClass()) return false;
1116	            TypedValue other = (TypedValue) obj;
1117	            return Objects.equals(value, other.value);
1118	        }
1119	
1120	        @Override
1121	        public String toString() {
1122	            return value;
1123	        }
1124	    }
1125	}
