        return new Cleaner(sl).clean(d).body().html();
    }
    static void t(String css) {
        String out = clean("<div style=\""+css+";color:red\">x</div>");
        System.out.println("IN : "+css);
        System.out.println("OUT: "+out);
        System.out.println();
    }
    public static void main(String[] a) {
        // hex escape that decodes to a letter of "url"
        t("background:\\75 rl(javascript:alert(1))");
        t("background:ur\\6c (javascript:alert(1))");
        t("background:\\75\\72\\6c(javascript:alert(1))");
        t("background:\\55 RL(javascript:alert(1))");
        t("background:u\\72 l(javascript:alert(1))");
        // char escapes
        t("background:\\u\\r\\l(javascript:alert(1))");
        t("background:\\uRL(javascript:alert(1))");
        // backslash sequences
        t("background:\\\\75rl(javascript:alert(1))");
        // expression variants
        t("background:\\65 xpression(alert(1))");
        t("background:expr\\65 ssion(alert(1))");
        t("background:\\65\\78\\70\\72\\65\\73\\73\\69\\6f\\6e(alert(1))");
        // nested inside other parens
        t("background:var(--x, \\75 rl(javascript:1))");
        // whitespace/control between
        t("background:\\75\tr\nl(javascript:1)");
        // escape split across weird boundary at end of input
        t("background:url(\\6a avascript:1)");
        // safe url with escaped name should be recognized and kept
        t("background:\\75 rl(https://example.com/x.png)");
        t("background:u\\72 l(https://example.com/x.png)");
        // free text (custom property / comment) variants
        t("--x: \\75 rl(javascript:1)");
        t("--x: \\65 xpression(1)");
        // @import hex?
        t("@\\69 mport 'javascript:1'");
    }
}
EOF
