private int skipSpaceAndComments(String value, int i, int end) {
    while (i < end) {
        char c = value.charAt(i);
        if (isCssSpace(c)) { i++; continue; }
        if (c == '/' && i + 1 < end && value.charAt(i + 1) == '*') {
