        show("hex LF delim safe", "background:\\75\nrl(https://example.com/x.png)");
        show("hex CR delim", "background:\\75\rrl(javascript:1)");
        show("hex tab delim", "background:\\75\trl(javascript:1)");
        show("hex FF delim", "background:\\75\frl(javascript:1)");
        // delimiter consumed means 'rl' glues; double whitespace: only first consumed, second is a real separator
        show("hex two spaces", "background:\\75  rl(javascript:1)");
