import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.*;
import java.util.Random;

public class Fuzz {
    public static void main(String[] a) {
        Safelist[] sls = {
            Safelist.relaxed().addAttributes(":all", "style"),
            new Safelist().addTags("div").addAttributes("div","style").addProtocols("div","style","data","http","https"),
            new Safelist().addTags("div").addAttributes("div","style").preserveRelativeLinks(true),
        };
        String[] bases = {"", "https://example.com/a/b", "https://ex.com/x/"};
        String alphabet = "url()javascript:1;\\ \t\n\r\f'\"@#%0xX6c7552465aeEexpressionvarcalc,/*-+0123456789abcdefABCDEF&;://.";
        Random r = new Random(42);
        int throwsCount = 0, unstable = 0, leak = 0;
        for (int n = 0; n < 200000; n++) {
            int len = r.nextInt(40);
            StringBuilder sb = new StringBuilder();
            for (int k = 0; k < len; k++) sb.append(alphabet.charAt(r.nextInt(alphabet.length())));
            String css = sb.toString();
            Safelist sl = sls[r.nextInt(sls.length)];
            String base = bases[r.nextInt(bases.length)];
            try {
                Document d1 = Jsoup.parseBodyFragment("<div style=\"" + css + "\">x</div>", base);
                Document c1 = new Cleaner(sl).clean(d1);
                String o1 = c1.body().html();
                Document c2 = new Cleaner(sl).clean(Jsoup.parseBodyFragment(o1, base));
                String o2 = c2.body().html();
                if (!o1.equals(o2)) {
                    if (unstable++ < 10) System.out.println("UNSTABLE css=["+css.replace("\n","\\n").replace("\r","\\r")+"] base="+base+"\n  "+o1+"\n  "+o2);
                }
                // leak check: a surviving style must not contain a plain/decoded javascript: fetchable reference
                if (o1.contains("style=")) {
                    String low = o1.toLowerCase();
                    // crude: look for javascript: that is outside obvious comment/string — just report counts
                    if (low.contains("javascript:") && !low.replaceAll("/\\*.*?\\*/","").replaceAll("'[^']*'","\"").replaceAll("&quot;[^&]*&quot;","\"").contains("javascript:")) {}
                }
            } catch (RuntimeException e) {
                if (throwsCount++ < 20) System.out.println("THROW css=["+css.replace("\n","\\n").replace("\r","\\r")+"]: "+e);
            }
        }
        System.out.println("done. throws="+throwsCount+" unstable="+unstable);
    }
}
