import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.*;
import java.util.Random;

public class FuzzLeak {
    public static void main(String[] a) {
        Safelist sl = Safelist.relaxed().addAttributes(":all", "style");
        String[] nameMuts = {
            "url", "URL", "Url", "\\75rl", "\\75 rl", "u\\72 l", "ur\\6c", "\\75\\72\\6c",
            "\\55\\52\\4c", "\\u\\r\\l", "\\uRL", "\\\\75rl", "\\\\u rl", "ur/**/l",
            "\\75/**/rl", "u/**/\\72 l", "\\000075 rl", "\\65xpression", "\\65 xpression",
            "EXPRESSION", "\\65\\78pression", "var(--x, url)", "calc(url)"
        };
        String[] urlMuts = {
            "javascript:1", "JAVASCRIPT:1", "vbscript:1", "java%73cript:1", "\\6a avascript:1",
            "&#1;javascript:1", "foo:bar", "//evil.com/x", "https://ok.com/x", "img/x.png"
        };
        String[] gap = {"", " ", "/**/", " /**/ ", "\t", "\n"};
        Random r = new Random(1);
        int leaks = 0, checked = 0;
        for (String nm : nameMuts) for (String u : urlMuts) for (int g = 0; g < gap.length; g++) {
            String inner = nm.replace("url", "urlX").replace("URL","URLX"); // ensure placeholder replacement unique
            // build the call: name + gap + ( + gap + arg + gap + )
            StringBuilder call = new StringBuilder(nm).append(gap[g]).append("(").append(gap[g]);
            // for nameMuts that are wrappers, place arg at X
            if (nm.contains("url)") || nm.endsWith(")")) {
                call = new StringBuilder(nm.replace("url)", "url("+u+")").replace("URL)","URL("+u+")"));
            } else call.append(u);
            call.append(gap[g]).append(")");
            String css = "background:" + call + ";color:red";
            Document d = Jsoup.parseBodyFragment("<div style=\""+css+"\">x</div>", "https://example.com/a/b");
            String out = new Cleaner(sl).clean(d).body().html();
            checked++;
            boolean dangerous = u.toLowerCase().contains("javascript") || u.contains("vbscript")
                || u.contains("foo:bar") || u.contains("//evil") || u.contains("%73") || u.contains("&#1")
                || u.contains("\\6a");
            // declarations that are actually a distinct, non-fetched tokenization may keep text but must not keep
            // a call whose decoded name is url/expression AND whose arg is dangerous.
            if (dangerous && out.toLowerCase().contains("javascript") && !out.contains("color:red\">x</div>") ) {
                // any surviving background besides the safe color?
                if (out.contains("background")) { if (leaks++ < 30) System.out.println("LEAK? ["+css+"] => "+out); }
            }
            // stronger invariant: cleaning the output again must not change it
            String out2 = new Cleaner(sl).clean(Jsoup.parseBodyFragment(out, "https://example.com/a/b")).body().html();
            if (!out.equals(out2)) { if (leaks++ < 30) System.out.println("UNSTABLE ["+css+"]\n  "+out+"\n  "+out2); }
        }
        System.out.println("checked="+checked+" leaks/unstable="+leaks);
    }
}
